import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { AreaChart, Area, BarChart, Bar, ResponsiveContainer, XAxis, YAxis, CartesianGrid, Tooltip as ChartTooltip } from 'recharts';
import { motion } from 'framer-motion';
import { Activity, ArrowLeft, ArrowRight, Award, Bell, Bookmark, BookmarkCheck, CalendarDays, Check, ChevronRight, CircleHelp, Clock3, Dumbbell, Flame, Heart, Home as HomeIcon, Info, Leaf, LineChart, ListFilter, LockKeyhole, MapPin, Menu, MessageCircle, MoreHorizontal, Pause, Play, Plus, Radio, Search, Settings, Share2, ShieldCheck, SkipForward, Sparkles, Star, Target, Timer, Trophy, Upload, UserRound, Users, Utensils, Video, WifiOff, X, Zap } from 'lucide-react';
