function GoalsPage() {
  const [goals, setGoals] = useState<Goal[]>(() => storage.get('athletiq-goals', defaultGoals));
  const [show, setShow] = useState(false);
  const [title, setTitle] = useState('');
  const save = (e: React.FormEvent) => { e.preventDefault(); if (!title.trim()) return; const next = [...goals, { id: `g${Date.now()}`, title, metric: 'sessions', target: 5, current: 0, unit: 'per week', due: '30 Jun', milestones: [{ label: 'Make it specific', done: true }, { label: 'Show up twice', done: false }, { label: 'Make it yours', done: false }] }]; setGoals(next); storage.set('athletiq-goals', next); setTitle(''); setShow(false); };
  const advance = (id: string) => { const next = goals.map((g) => g.id === id ? { ...g, current: Math.min(g.target, g.current + 1), milestones: g.milestones.map((m, i) => i === g.milestones.findIndex((x) => !x.done) ? { ...m, done: true } : m) } : g); setGoals(next); storage.set('athletiq-goals', next); };
  return <div className="mx-auto max-w-[1200px] px-4 py-7 sm:px-7 lg:px-10"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-xs uppercase tracking-[.18em] text-primary">The long game</p><h1 className="mt-2 font-display text-5xl font-black uppercase sm:text-6xl">Goals with a pulse.</h1><p className="mt-3 text-sm text-muted-foreground">Keep the destination visible. Let the daily work be small.</p></div><Button onClick={() => setShow(true)} data-testid="button-create-goal"><Plus size={17} />New goal</Button></div><div className="mt-8 grid gap-5 md:grid-cols-2">{goals.map((goal) => <div key={goal.id} className="rounded-2xl border border-border bg-card p-6"><div className="flex items-start justify-between"><div><Pill tone={goal.current >= goal.target ? 'green' : 'teal'}>{goal.current >= goal.target ? 'Complete' : 'In progress'}</Pill><h2 className="mt-3 font-display text-3xl font-bold uppercase">{goal.title}</h2><p className="mt-1 text-sm text-muted-foreground">By {goal.due} · {goal.metric}</p></div><button onClick={() => advance(goal.id)} className="grid h-10 w-10 place-items-center rounded-xl bg-accent/15 text-accent hover:bg-accent" data-testid={`button-advance-goal-${goal.id}`}><Plus size={18} /></button></div><div className="mt-7 flex items-end justify-between"><span className="font-mono text-2xl">{goal.current} <span className="text-sm text-muted-foreground">/ {goal.target} {goal.unit}</span></span><span className="text-sm font-bold text-primary">{Math.round(Math.min(1, goal.current / goal.target) * 100)}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${Math.min(100, goal.current / goal.target * 100)}%` }} /></div><div className="mt-6 space-y-3">{goal.milestones.map((m) => <div key={m.label} className={`flex items-center gap-3 text-sm ${m.done ? 'text-foreground' : 'text-muted-foreground'}`}><span className={`grid h-6 w-6 place-items-center rounded-full border ${m.done ? 'border-primary bg-primary text-primary-foreground' : 'border-border'}`}>{m.done && <Check size={13} />}</span>{m.label}</div>)}</div></div>)}</div><div className="mt-8 rounded-2xl bg-sidebar p-6 text-sidebar-foreground sm:p-8"><div className="flex flex-wrap items-center justify-between gap-5"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">One good move</p><h2 className="mt-2 font-display text-4xl font-black uppercase">The plan is the promise.</h2><p className="mt-2 max-w-lg text-sm text-sidebar-foreground/60">Goals get useful when they change what you do today. Add a rep, take a walk, prepare the meal.</p></div><Link href="/train" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-accent px-4 text-sm font-bold text-accent-foreground" data-testid="link-goals-train">Find today’s move <ArrowRight size={16} /></Link></div></div>{show && <div className="fixed inset-0 z-40 grid place-items-center bg-sidebar/60 p-4 backdrop-blur-sm"><form onSubmit={save} className="w-full max-w-md rounded-3xl bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-display text-3xl font-bold uppercase">New goal</h2><button type="button" onClick={() => setShow(false)} data-testid="button-close-goal"><X size={19} /></button></div><label className="mt-7 block text-sm font-bold">What are you working toward?</label><input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Run my first 5K" className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 outline-none focus:ring-2 focus:ring-primary" data-testid="input-goal-title" /><Button type="submit" className="mt-5 w-full" data-testid="button-save-goal">Create goal <ArrowRight size={16} /></Button></form></div>}</div>;
}

function RahulPage() {
  const athlete = storage.get<Athlete>('athletiq-athlete', { name: 'Athlete', sport: 'Football', level: 'Intermediate', position: 'Winger', goals: ['Speed'], preferences: [] });
  const [messages, setMessages] = useState<{ from: 'rahul' | 'you'; text: string }[]>([{ from: 'rahul', text: `Hey ${athlete.name}. I’ve got your ${athlete.sport.toLowerCase()} context. What do you want to sharpen today?` }]);
  const [input, setInput] = useState('');
  const send = async (text = input) => {
    const message = text.trim();
    if (!message) return;
    setMessages((m) => [...m, { from: 'you', text: message }]);
    setInput('');
    try {
      const response = await fetch('/api/rahul/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message, athlete }),
      });
      const result = await response.json() as { reply?: string; error?: string };
      if (!response.ok || !result.reply) throw new Error(result.error || 'Rahul is unavailable');
      setMessages((m) => [...m, { from: 'rahul', text: result.reply! }]);
    } catch {
      setMessages((m) => [...m, { from: 'rahul', text: 'I’m having trouble reaching the AI coach right now. Try again in a moment.' }]);
    }
  };
  return <div className="mx-auto max-w-4xl px-4 py-7 sm:px-7 lg:py-10"><div className="rounded-[1.8rem] bg-sidebar p-6 text-sidebar-foreground sm:p-9"><div className="flex items-center gap-4"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-accent text-accent-foreground"><Sparkles size={27} /></span><div><Pill tone="orange">DEMO RAHUL</Pill><h1 className="mt-1 font-display text-4xl font-black uppercase">Your coach, in the pocket.</h1></div></div><p className="mt-5 max-w-xl text-sm leading-relaxed text-sidebar-foreground/60">A demo coaching layer using your sport, level, goals, and training history. Useful guidance, not medical advice.</p></div><div className="mt-5 rounded-2xl border border-border bg-card"><div className="min-h-[360px] space-y-4 p-5 sm:p-7">{messages.map((m, i) => <div key={`${m.from}-${i}`} className={`flex gap-3 ${m.from === 'you' ? 'justify-end' : ''}`}><div className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm leading-relaxed ${m.from === 'you' ? 'bg-primary text-primary-foreground' : 'bg-muted'}`}>{m.text}</div></div>)}</div><div className="border-t border-border p-4"><div className="scrollbar-none flex gap-2 overflow-x-auto pb-3">{['What should I train today?', 'How do I recover?', 'What should I eat?'].map((p) => <button key={p} onClick={() => send(p)} className="shrink-0 rounded-full border border-border px-3 py-2 text-xs font-bold hover:border-primary hover:text-primary" data-testid={`button-prompt-${p.slice(0, 5).toLowerCase()}`}>{p}</button>)}</div><form onSubmit={(e) => { e.preventDefault(); send(); }} className="flex gap-2"><input value={input} onChange={(e) => setInput(e.target.value)} placeholder="Ask Rahul something useful..." className="h-12 min-w-0 flex-1 rounded-xl border border-input bg-background px-4 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-rahul-message" /><Button type="submit" data-testid="button-send-rahul"><ArrowRight size={17} /></Button></form></div></div></div>;
}

function NutritionPage() {
  return <div className="mx-auto max-w-[1200px] px-4 py-7 sm:px-7 lg:px-10"><p className="font-mono text-xs uppercase tracking-[.18em] text-primary">Performance fuel</p><h1 className="mt-2 font-display text-5xl font-black uppercase sm:text-6xl">Eat for the work.</h1><p className="mt-3 max-w-2xl text-sm leading-relaxed text-muted-foreground">General guidance for training days. Choose what is familiar, affordable, and kind to your stomach.</p><div className="mt-8 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="rounded-2xl bg-sidebar p-6 text-sidebar-foreground sm:p-8"><div className="flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-accent text-accent-foreground"><Utensils size={21} /></span><Pill tone="orange">Training day plate</Pill></div><h2 className="mt-6 font-display text-5xl font-black uppercase leading-[.9]">Build around<br /><span className="text-accent">the session.</span></h2><div className="mt-8 grid grid-cols-3 gap-2 border-t border-sidebar-border pt-5 text-center"><div><b className="font-display text-2xl text-accent">1/2</b><p className="text-[11px] text-sidebar-foreground/55">colourful carbs</p></div><div><b className="font-display text-2xl text-accent">1/4</b><p className="text-[11px] text-sidebar-foreground/55">protein</p></div><div><b className="font-display text-2xl text-accent">1/4</b><p className="text-[11px] text-sidebar-foreground/55">plants + fats</p></div></div></div><div className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/10 text-primary"><Activity size={19} /></span><div><h2 className="font-display text-2xl font-bold uppercase">Hydration check</h2><p className="text-xs text-muted-foreground">Start before you feel thirsty</p></div></div><div className="mt-7 flex items-end gap-2"><b className="font-display text-6xl text-primary">2.4</b><span className="mb-2 font-mono text-xs">L / day</span></div><p className="mt-2 text-sm leading-relaxed text-muted-foreground">Add more in heat, altitude, or longer sessions. A pinch of salt and a squeeze of lime can help after heavy sweat.</p><div className="mt-5 h-3 overflow-hidden rounded-full bg-muted"><div className="h-full w-[62%] rounded-full bg-primary" /></div></div></div><div className="mt-10"><SectionHeading eyebrow="A few good options" title="Plates that travel well" /><div className="grid gap-4 md:grid-cols-2"><MealCard title="Indian training plate" flag="INDIA" items="Dal · rice · curd · cucumber · banana" note="Warm, familiar, high in carbohydrate and easy to scale." /><MealCard title="International training plate" flag="GLOBAL" items="Eggs · sourdough · avocado · berries · yoghurt" note="A flexible option when you want a lighter pre-session meal." /><MealCard title="Between sessions" flag="QUICK" items="Peanut chikki · fruit · milk or soy shake" note="Small enough to eat, useful enough to bridge the gap." /><MealCard title="Late finish" flag="EASY" items="Paneer wrap · lentil soup · roasted vegetables" note="Comforting fuel with protein for overnight repair." /></div></div><div className="mt-8 flex gap-3 rounded-2xl border border-amber-300 bg-amber-50 p-5 text-sm text-amber-950"><Info className="mt-0.5 shrink-0" size={18} /><p><b>General guidance, not medical advice.</b> Needs vary with age, body size, training load, allergies, and health conditions. Speak with a qualified sports dietitian for personal advice.</p></div></div>;
}
function MealCard({ title, flag, items, note }: { title: string; flag: string; items: string; note: string }) { return <div className="card-lift rounded-2xl border border-border bg-card p-5"><div className="flex items-center justify-between"><Pill tone="teal">{flag}</Pill><Utensils size={18} className="text-accent" /></div><h3 className="mt-6 font-display text-2xl font-bold uppercase">{title}</h3><p className="mt-2 font-bold">{items}</p><p className="mt-3 text-sm leading-relaxed text-muted-foreground">{note}</p></div>; }

function FeedPage() {
  const [posts, setPosts] = useState(() => socialPosts);
  const [following, setFollowing] = useState<string[]>([]);
  const [newPost, setNewPost] = useState('');
  const [commenting, setCommenting] = useState<string | null>(null);
  const [comment, setComment] = useState('');
  const [comments, setComments] = useState<Record<string, string[]>>({});
  const toggleLike = (id: string) => setPosts((p) => p.map((x) => x.id === id ? { ...x, liked: !x.liked, likes: x.likes + (x.liked ? -1 : 1) } : x));
  const addPost = (e: React.FormEvent) => { e.preventDefault(); if (!newPost.trim()) return; const athlete = storage.get<Athlete>('athletiq-athlete', { name: 'Athlete' } as Athlete); setPosts((p) => [{ id: `mine-${Date.now()}`, author: athlete.name, handle: 'you', role: 'Athlete', initials: athlete.name.slice(0, 2).toUpperCase(), color: '#008c99', text: newPost, time: 'just now', likes: 0, comments: 0, tags: ['my-training'] }, ...p]); setNewPost(''); };
  const addComment = (e: React.FormEvent, id: string) => { e.preventDefault(); if (!comment.trim()) return; setComments((c) => ({ ...c, [id]: [...(c[id] || []), comment.trim()] })); setPosts((p) => p.map((x) => x.id === id ? { ...x, comments: x.comments + 1 } : x)); setComment(''); };
  return <div className="mx-auto max-w-5xl px-4 py-7 sm:px-7 lg:py-10"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-xs uppercase tracking-[.18em] text-primary">The training room</p><h1 className="mt-2 font-display text-5xl font-black uppercase sm:text-6xl">Show your work.</h1><p className="mt-3 text-sm text-muted-foreground">DEMO ATHLETIQ FEED · A little accountability goes a long way.</p></div><Button onClick={() => document.getElementById('create-post')?.focus()} variant="secondary" data-testid="button-create-post"><Plus size={17} />Post update</Button></div><form onSubmit={addPost} className="mt-7 rounded-2xl border border-border bg-card p-4"><div className="flex gap-3"><Avatar name="You" color="#008c99" small /><input id="create-post" value={newPost} onChange={(e) => setNewPost(e.target.value)} placeholder="What did you learn today?" className="min-w-0 flex-1 bg-transparent text-sm outline-none" data-testid="input-create-post" /><Button type="submit" className="hidden sm:inline-flex" data-testid="button-publish-post">Publish</Button></div>{newPost && <Button type="submit" className="mt-3 w-full sm:hidden" data-testid="button-publish-post-mobile">Publish update</Button>}</form><div className="mt-7 space-y-4">{posts.map((post) => <article key={post.id} className="rounded-2xl border border-border bg-card p-5"><div className="flex items-start gap-3"><Avatar name={post.initials} color={post.color} small /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><b>{post.author}</b><span className="text-xs text-muted-foreground">@{post.handle}</span><span className="text-muted-foreground">·</span><span className="text-xs text-muted-foreground">{post.time}</span></div><p className="text-xs text-muted-foreground">{post.role}</p></div><button className="grid h-9 w-9 place-items-center rounded-lg text-muted-foreground hover:bg-muted" data-testid={`button-post-more-${post.id}`}><MoreHorizontal size={18} /></button></div><p className="mt-5 text-sm leading-relaxed">{post.text}</p><div className="mt-4 flex flex-wrap gap-2">{post.tags.map((tag) => <span key={tag} className="text-xs font-bold text-primary">#{tag}</span>)}</div><div className="mt-5 flex items-center gap-5 border-t border-border pt-3"><button onClick={() => toggleLike(post.id)} className={`flex min-h-9 items-center gap-1.5 text-xs font-bold ${post.liked ? 'text-accent' : 'text-muted-foreground'}`} data-testid={`button-like-${post.id}`}><Heart size={17} fill={post.liked ? 'currentColor' : 'none'} />{post.likes}</button><button onClick={() => setCommenting(commenting === post.id ? null : post.id)} className="flex min-h-9 items-center gap-1.5 text-xs font-bold text-muted-foreground" data-testid={`button-comment-${post.id}`}><MessageCircle size={17} />{post.comments}</button><button onClick={() => navigator.clipboard?.writeText(post.text)} className="ml-auto flex min-h-9 items-center gap-1.5 text-xs font-bold text-muted-foreground" data-testid={`button-share-${post.id}`}><Share2 size={16} />Share</button><button onClick={() => setFollowing((f) => f.includes(post.handle) ? f.filter((x) => x !== post.handle) : [...f, post.handle])} className="text-xs font-bold text-primary" data-testid={`button-follow-${post.id}`}>{following.includes(post.handle) ? 'Following' : 'Follow'}</button></div>{commenting === post.id && <form onSubmit={(e) => addComment(e, post.id)} className="mt-3 flex gap-2"><input autoFocus value={comment} onChange={(e) => setComment(e.target.value)} placeholder="Add a useful thought..." className="h-10 min-w-0 flex-1 rounded-lg border border-input bg-background px-3 text-xs outline-none focus:ring-2 focus:ring-primary" data-testid={`input-comment-${post.id}`} /><button type="submit" className="grid h-10 w-10 place-items-center rounded-lg bg-primary text-primary-foreground" data-testid={`button-submit-comment-${post.id}`}><ArrowRight size={15} /></button></form>}{comments[post.id]?.map((text, i) => <p key={`${post.id}-comment-${i}`} className="mt-2 rounded-lg bg-muted px-3 py-2 text-xs"><b>You:</b> {text}</p>)}</article>)}</div></div>;
}

function LivePage() {
  const [watching, setWatching] = useState<string | null>(null);
  const [booked, setBooked] = useState<string[]>([]);
  const [setup, setSetup] = useState(false);
  return <div className="mx-auto max-w-[1400px] px-4 py-7 sm:px-7 lg:px-10"><div className="rounded-[1.8rem] bg-sidebar p-6 text-sidebar-foreground sm:p-9"><div className="flex flex-wrap items-end justify-between gap-6"><div><Pill tone="orange">DEMO STREAM MODE</Pill><h1 className="mt-4 font-display text-5xl font-black uppercase leading-[.9] sm:text-7xl">See how<br /><span className="text-accent">great moves.</span></h1><p className="mt-5 max-w-md text-sm leading-relaxed text-sidebar-foreground/60">Demo match coverage, athlete sessions, and live events from the Athletiq network. No real broadcast rights or live data.</p><Button onClick={() => setSetup(true)} className="mt-6" data-testid="button-go-live"><Radio size={16} />Set up a demo stream</Button></div><div className="w-full max-w-xs rounded-2xl border border-sidebar-border bg-sidebar-accent p-4"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Your facility map</p><div className="mt-4 space-y-2">{facilities.slice(0, 3).map((f, i) => <div key={f} className="flex items-center gap-2 text-sm"><MapPin size={14} className="text-accent" />{f}<span className="ml-auto text-xs text-sidebar-foreground/45">{2 + i * 3}.{i} km</span></div>)}</div><Button variant="secondary" className="mt-4 w-full" onClick={() => alert('DEMO: facility booking request saved.')} data-testid="button-book-facility">Book a facility</Button></div></div></div><div className="mt-9 flex items-center justify-between"><SectionHeading eyebrow="DEMO MATCH DATA" title="Live & upcoming" /><Pill tone="teal">{matches.length} events</Pill></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{matches.map((match) => <div key={match.id} className="card-lift overflow-hidden rounded-2xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border bg-muted/50 px-4 py-3"><span className={`flex items-center gap-2 text-xs font-bold ${match.status === 'LIVE' ? 'text-accent' : 'text-muted-foreground'}`}><i className={`h-2 w-2 rounded-full ${match.status === 'LIVE' ? 'animate-pulse bg-accent' : 'bg-muted-foreground'}`} />{match.status === 'LIVE' ? 'LIVE NOW' : match.time}</span><span className="font-mono text-[10px] text-muted-foreground">{match.viewers} viewers</span></div><div className="p-5"><p className="font-mono text-[10px] uppercase tracking-[.15em] text-primary">{match.league} · {match.sport}</p><h3 className="mt-5 font-display text-3xl font-bold uppercase">{match.teams}</h3><p className="mt-2 flex items-center gap-1 text-xs text-muted-foreground"><MapPin size={13} />{match.venue}</p><div className="mt-5 flex gap-2"><Button onClick={() => setWatching(match.id)} className="flex-1" data-testid={`button-watch-${match.id}`}><Play size={15} fill="currentColor" />{match.status === 'LIVE' ? 'Watch' : 'Remind me'}</Button><button onClick={() => setBooked((b) => b.includes(match.id) ? b.filter((x) => x !== match.id) : [...b, match.id])} className={`grid h-11 w-11 place-items-center rounded-xl border ${booked.includes(match.id) ? 'border-accent bg-accent/15 text-accent' : 'border-border text-muted-foreground'}`} data-testid={`button-remind-${match.id}`}><CalendarDays size={17} /></button></div></div></div>)}</div>{setup && <div className="fixed inset-0 z-40 grid place-items-center bg-sidebar/70 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-3xl bg-card p-6"><div className="flex items-center justify-between"><div><Pill tone="orange">DEMO STREAM MODE</Pill><h2 className="mt-3 font-display text-3xl font-bold uppercase">Set your broadcast</h2></div><button onClick={() => setSetup(false)} data-testid="button-close-go-live"><X size={18} /></button></div><p className="mt-3 text-sm text-muted-foreground">Choose a camera source for the simulated athlete stream.</p><div className="mt-5 space-y-2">{['Phone camera', 'Training facility camera', 'Screen only'].map((option, i) => <button key={option} onClick={() => setSetup(false)} className="flex min-h-12 w-full items-center gap-3 rounded-xl border border-border px-4 text-left text-sm font-bold hover:border-primary" data-testid={`button-stream-source-${i}`}><Radio size={16} className="text-primary" />{option}<ChevronRight className="ml-auto" size={16} /></button>)}</div></div></div>}{watching && <div className="fixed inset-0 z-40 grid place-items-center bg-sidebar/80 p-4 backdrop-blur-sm"><div className="w-full max-w-2xl overflow-hidden rounded-3xl bg-sidebar-accent text-sidebar-foreground shadow-2xl"><div className="relative grid aspect-video place-items-center bg-[radial-gradient(circle_at_50%_35%,#14606a,#0d2026_65%)]"><span className="grid h-16 w-16 place-items-center rounded-full bg-accent text-accent-foreground"><Play size={27} fill="currentColor" /></span><span className="absolute left-4 top-4"><Pill tone="orange">DEMO STREAM MODE</Pill></span></div><div className="flex items-center justify-between p-5"><div><h2 className="font-display text-2xl font-bold uppercase">{matches.find((m) => m.id === watching)?.teams}</h2><p className="text-xs text-sidebar-foreground/55">Simulated stream · no external video</p></div><button onClick={() => setWatching(null)} className="grid h-10 w-10 place-items-center rounded-xl bg-sidebar" data-testid="button-close-stream"><X size={18} /></button></div></div></div>}</div>;
}

function ProfilePage() {
  const [athlete, setAthlete] = useState<Athlete>(() => storage.get('athletiq-athlete', { name: 'Athlete', sport: 'Football', level: 'Intermediate', position: 'Winger', goals: ['Speed'], preferences: [] }));
  const [editing, setEditing] = useState(false);
  const [offline, setOffline] = useState(false);
  const save = () => { storage.set('athletiq-athlete', athlete); setEditing(false); };
  return <div className="mx-auto max-w-5xl px-4 py-7 sm:px-7 lg:py-10"><div className="rounded-[1.8rem] bg-sidebar p-6 text-sidebar-foreground sm:p-9"><div className="flex flex-wrap items-center gap-5"><Avatar name={athlete.name} color="#e87845" /><div className="flex-1"><Pill tone="orange">Athlete profile</Pill><h1 className="mt-2 font-display text-5xl font-black uppercase">{athlete.name}</h1><p className="mt-1 text-sm text-sidebar-foreground/55">{athlete.sport} · {athlete.position} · {athlete.level}</p></div><Button variant="secondary" onClick={() => setEditing(!editing)} data-testid="button-edit-profile">{editing ? 'Cancel' : 'Edit profile'}</Button></div></div><div className="mt-7 grid gap-5 lg:grid-cols-[1fr_320px]"><div className="space-y-5">{editing ? <div className="rounded-2xl border border-border bg-card p-6"><h2 className="font-display text-3xl font-bold uppercase">Your details</h2><label className="mt-5 block text-xs font-bold uppercase tracking-wider text-muted-foreground">Name</label><input value={athlete.name} onChange={(e) => setAthlete({ ...athlete, name: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3 outline-none focus:ring-2 focus:ring-primary" data-testid="input-profile-name" /><label className="mt-4 block text-xs font-bold uppercase tracking-wider text-muted-foreground">Position / event</label><input value={athlete.position} onChange={(e) => setAthlete({ ...athlete, position: e.target.value })} className="mt-2 h-11 w-full rounded-xl border border-input bg-background px-3 outline-none focus:ring-2 focus:ring-primary" data-testid="input-profile-position" /><Button onClick={save} className="mt-5 w-full" data-testid="button-save-profile">Save profile <Check size={16} /></Button></div> : <div className="rounded-2xl border border-border bg-card p-6"><SectionHeading eyebrow="Identity" title="Your settings" /><div className="grid gap-3 sm:grid-cols-2">{[['Sport', athlete.sport], ['Level', athlete.level], ['Position', athlete.position], ['Training style', athlete.preferences.join(', ') || 'Flexible']].map(([a, b]) => <div key={a} className="rounded-xl bg-muted p-4"><p className="text-xs text-muted-foreground">{a}</p><p className="mt-1 font-bold">{b}</p></div>)}</div></div>}<div className="rounded-2xl border border-border bg-card p-6"><SectionHeading eyebrow="Proof of work" title="Achievements" /><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{[['First session', Check], ['Four day streak', Flame], ['Goal setter', Target], ['Good teammate', Users]].map(([label, Icon]) => { const I = Icon as typeof Check; return <div key={label as string} className="rounded-xl border border-border p-4 text-center"><span className="mx-auto grid h-11 w-11 place-items-center rounded-full bg-accent/15 text-accent"><I size={19} /></span><p className="mt-3 text-xs font-bold">{label as string}</p></div>; })}</div></div></div><aside className="space-y-5"><div className="rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-muted-foreground">Connection</p><h2 className="mt-1 font-display text-3xl font-bold uppercase">{offline ? 'Offline mode' : 'Synced locally'}</h2></div><WifiOff className={offline ? 'text-accent' : 'text-primary'} size={23} /></div><p className="mt-3 text-sm leading-relaxed text-muted-foreground">{offline ? 'Your plan is still here. Changes will stay on this device.' : 'All demo data is saved on this device.'}</p><button onClick={() => setOffline(!offline)} className="mt-5 text-sm font-bold text-primary" data-testid="button-toggle-offline">{offline ? 'Mark as connected' : 'Simulate offline'}</button></div><div className="rounded-2xl border border-border bg-card p-6"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-primary">Privacy</p><h2 className="mt-2 font-display text-3xl font-bold uppercase">Your data, your device.</h2><p className="mt-2 text-sm leading-relaxed text-muted-foreground">This demo uses local storage only. Nothing leaves this browser.</p><button onClick={() => { localStorage.clear(); window.location.reload(); }} className="mt-5 text-sm font-bold text-destructive" data-testid="button-reset-data">Reset demo data</button></div></aside></div></div>;
}

function AppRouter() {
  return <Switch><Route path="/" component={AuthPage} /><Route path="/onboarding" component={OnboardingPage} /><Route path="/home"><Shell><HomePage /></Shell></Route><Route path="/train"><Shell><TrainPage /></Shell></Route><Route path="/workout/:id"><Shell><WorkoutPage /></Shell></Route><Route path="/progress"><Shell><PerformancePage /></Shell></Route><Route path="/performance"><Shell><PerformancePage /></Shell></Route><Route path="/goals"><Shell><GoalsPage /></Shell></Route><Route path="/rahul"><Shell><RahulPage /></Shell></Route><Route path="/nutrition"><Shell><NutritionPage /></Shell></Route><Route path="/video-analysis"><Shell><VideoAnalysisPage /></Shell></Route><Route path="/notifications"><Shell><NotificationsPage /></Shell></Route><Route path="/feed"><Shell><FeedPage /></Shell></Route><Route path="/live"><Shell><LivePage /></Shell></Route><Route path="/profile"><Shell><ProfilePage /></Shell></Route><Route><NotFound /></Route></Switch>;
}
function NotFound() { const [, setLocation] = useLocation(); return <div className="grid min-h-[100dvh] place-items-center bg-sidebar p-6 text-center text-sidebar-foreground"><div><Logo /><p className="mt-16 font-mono text-xs text-accent">404 · OUT OF BOUNDS</p><h1 className="mt-3 font-display text-6xl font-black uppercase">Wrong turn.</h1><Button onClick={() => setLocation('/')} className="mt-7" data-testid="button-404-home">Back to start</Button></div></div>; }
function Router() { return <ErrorBoundary><AppRouter /></ErrorBoundary>; }
export default function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }